package org.eurorig.routing.parking;
import static org.junit.Assert.*;import org.junit.Test;import java.util.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.io.*;
public class ParkingEvidenceTest {
    final long now=java.time.Instant.parse("2026-10-21T15:22:30Z").toEpochMilli();
    Parking.Site site(boolean exclusive){return new Parking.Site("fixture","site","1","Original test parking",51,6,"optional",Map.of("truck",new Parking.Group("truck",20,true,exclusive,true)),List.of(new Parking.Entrance("entry",51,6,"A1","East")));}
    Parking.Table table(Parking.Site site,String information){return new Parking.Table("t","1",information,now,List.of(site));}
    Parking.Status status(long measured,String condition,Integer vacant,Integer occupied){return new Parking.Status("t","1",now,Map.of("site",new Parking.Observation("site","1",condition,measured,true,Map.of("truck",new Parking.Count(vacant,occupied,true)))));}
    @Test public void exactRequiresFreshExplicitTruckOnlyReliableEvidence(){Parking.Site s=site(true);Parking.Availability a=Parking.availability(table(s,"real"),status(now-60_000,"spacesAvailable",5,15),s,now,true);assertEquals(Integer.valueOf(5),a.spaces);assertEquals("Truck parking in 3 kilometres. 5 spaces reported available, updated 1 minute ago. Spaces are not guaranteed on arrival.",Parking.speech(3000,a,now));}
    @Test public void staleFutureMissingDisconnectedOrTestCannotBeLive(){Parking.Site s=site(true);for(long measured:new long[]{0,now-180_001,now+30_001})assertFalse(Parking.availability(table(s,"real"),status(measured,"spacesAvailable",5,15),s,now,true).exact());assertFalse(Parking.availability(table(s,"test"),status(now,"spacesAvailable",5,15),s,now,true).exact());assertFalse(Parking.availability(table(s,"real"),status(now,"spacesAvailable",5,15),s,now,false).exact());assertFalse(Parking.availability(table(s,"real"),status(now,"spacesAvailable",null,15),s,now,true).exact());}
    @Test public void zeroUnknownConflictsAndSharedOrMismatchedGroupsAreNotAvailability(){Parking.Site s=site(true);for(String condition:new String[]{"statusUnknown","closed","spacesAvailable",""})assertFalse(Parking.availability(table(s,"real"),status(now,condition,0,20),s,now,true).exact());assertEquals(Integer.valueOf(0),Parking.availability(table(s,"real"),status(now,"full",0,20),s,now,true).spaces);for(int count:new int[]{-1,21,30})assertFalse(Parking.availability(table(s,"real"),status(now,"spacesAvailable",count,0),s,now,true).exact());assertFalse(Parking.availability(table(s,"real"),status(now,"spacesAvailable",5,19),s,now,true).exact());Parking.Site shared=site(false);assertFalse(Parking.availability(table(shared,"real"),status(now,"spacesAvailable",5,15),shared,now,true).exact());Parking.Status mismatch=new Parking.Status("other","1",now,status(now,"spacesAvailable",5,15).observations);assertFalse(Parking.availability(table(s,"real"),mismatch,s,now,true).exact());}
    @Test public void actualNdwSnapshotPreservesTestFlagAndNeverUsesVehicleTotals()throws Exception{NdwParkingProvider provider=new NdwParkingProvider();Parking.Table table=provider.table(Files.readAllBytes(Path.of("src/test/resources/parking/ndw-table-2026-10-21.xml")));Parking.Status status=provider.status(Files.readAllBytes(Path.of("src/test/resources/parking/ndw-status-2026-10-21.xml")));assertEquals(8,table.sites.size());assertEquals(8,status.observations.size());assertEquals("test",table.informationStatus);assertEquals("97",table.version);for(Parking.Site site:table.sites){assertFalse(site.entrances.isEmpty());assertFalse(Parking.availability(table,status,site,now,true).exact());}Parking.Site venlo=table.sites.stream().filter(s->s.id.equals("NL-12_421")).findFirst().get();assertEquals("Truckstop Venlo",venlo.name);assertEquals(390,venlo.groups.get("0").capacity);assertEquals(51.390896,venlo.entrances.get(0).lat,.000001);}
    @Test public void externalEntityAndDoctypeAreRejectedWithoutAccessingFiles()throws Exception{String xml="<!DOCTYPE data [<!ENTITY secret SYSTEM 'file:///not-readable'>]><data>&secret;</data>";try{new NdwParkingProvider().table(xml.getBytes(StandardCharsets.UTF_8));fail("DTD accepted");}catch(IOException expected){assertTrue(expected.getMessage().contains("unsafe"));}}
}
